        'skill.capacidadMochila4.desc':    "+20% adicional de capacidade de carga (+80% no total).",
        'skill.capacidadMochila5.name':    "Mochila Reforçada V",
        'skill.capacidadMochila5.desc':    "+20% adicional de capacidade de carga (+100% no total).",
        'skill.velocidadAldeano.name':     "Passo Ligeiro",
        'skill.velocidadAldeano.desc':     "Todos os aldeões se movem 20% mais rápido.",
        'skill.velocidadAldeano2.name':    "Passo Ligeiro II",
        'skill.velocidadAldeano2.desc':    "+20% adicional de velocidade de movimento (+40% no total).",
