        'ctrl.key_drag':                   "Ziehen ({dragInput})",
        'ctrl.key_wheel':                  "{wheelInput} / +‑ Knöpfe",
        'ctrl.mission_label':              "Ziel:",
        'ctrl.left_click':                 "Auswählen / Bauen",
