        'credits.audio':                   "Musik und Ton",
        'credits.audio_list':              "Musik: Kevin MacLeod (<a href=\"https://incompetech.com/\" target=\"_blank\" rel=\"noopener\" style=\"color:var(--text-muted);\">incompetech.com</a>), CC BY 4.0<br>Effekte: <a href=\"https://kenney.nl/\" target=\"_blank\" rel=\"noopener\" style=\"color:var(--text-muted);\">Kenney</a>, <a href=\"https://opengameart.org/\" target=\"_blank\" rel=\"noopener\" style=\"color:var(--text-muted);\">OpenGameArt</a> und <a href=\"https://freesound.org/\" target=\"_blank\" rel=\"noopener\" style=\"color:var(--text-muted);\">Freesound</a> (CC0)<br>Streik: „Voices Angry“, <a href=\"https://developers.google.com/assistant/tools/sound-library\" target=\"_blank\" rel=\"noopener\" style=\"color:var(--text-muted);\">Google Sound Library</a>, <a href=\"https://creativecommons.org/licenses/by/4.0/\" target=\"_blank\" rel=\"noopener\" style=\"color:var(--text-muted);\">CC BY 4.0</a>",
        'world.choose_title':              "Wo beginnt diese Partie?",
        'world.choose_desc':               "Du hast Welt 1 abgeschlossen. Du kannst sie neu beginnen oder in Welt 2 Schiffbruch erleiden.",
        'world.1.name':                    "Welt 1 · Der Wald",
        'world.1.desc':                    "Du startest wie immer in der Kartenmitte.",
        'world.2.name':                    "Welt 2 · Die Küste",
        'world.2.desc':                    "Dein Schiff zerschellt an der Südküste. Du fängst bei null an und fällst dich nach Norden vor: Je weiter, desto härter die Bäume.",
        'world.cancel':                    "Abbrechen",
        'world.done_title':                "Welt 1 abgeschlossen",
        'world.done_desc':                 "Deine Expedition hat abgelegt. Welt 2 wartet an der Küste. Gehst du dorthin, wird diese Partie durch eine neue in Welt 2 ersetzt, ganz von vorn: Nur deine Erfolge nimmst du mit. Wenn du sie behalten willst, lade vorher eine Kopie herunter.",
        'world.go_w2':                     "Auf zu Welt 2",
        'w2intro.title':                   "Schiffbruch!",
        'w2intro.p1':                      "Die Karavelle segelte wochenlang mit {n} Bewohnern an Bord dem Horizont entgegen… bis ein Sturm sie an den Riffen einer unbekannten Küste zerschmetterte.",
        'w2intro.p2':                      "Nur zwei Überlebende erreichten mit dir das Ufer. Vom Schiff ist nichts übrig: Alles beginnt von vorn. Fälle dich nach Norden vor, such Relikte und bau ein neues Dorf am Meer.",
        'w2intro.go':                      "Neu anfangen",
        'w2done.title':                    "Welt 2 abgeschlossen",
        'w2done.p1':                       "Du hast alle Vermächtnisse der Küste errungen. Aus dem Schiffbruch wurde ein blühendes Dorf mit Häfen, Booten und Leuchttürmen am Meer.",
        'w2done.p2':                       "Doch im Norden, im Gebirge, sind alte Tore noch verschlossen. Man sagt, dahinter beginnt Welt 3… Demnächst.",
        'w2done.p2_hidden':                "Doch im Norden, hinter dem Gebirge, soll es alte, verschlossene Tore geben. Dahinter würde Welt 3 beginnen… Demnächst.",
        'w2done.see_gates':                "Die Tore ansehen",
        'w2done.keep':                     "Weiterspielen",
        'repair.auto':                     "Wir haben ein Problem in deinem Spielstand gefunden und es repariert.",
        'repair.title':                    "Spielstand prüfen",
        'repair.intro':                    "In deinem Spielstand stimmt etwas nicht. Du kannst es hier beheben: Nur was kaputt ist, wird angefasst.",
        'repair.ok_all':                   "Alles in Ordnung: Wir haben keine Probleme in deinem Spielstand gefunden.",
        'repair.fix':                      "Beheben",
        'repair.fix_all':                  "Alles beheben",
        'repair.close':                    "Schließen",
        'repair.done':                     "Spielstand repariert.",
        'repair.unavailable':              "Prüfung gerade nicht möglich (Herausforderung oder fremde Stadt).",
        'repair.skills_dropped':           "Fähigkeiten aus deiner vorherigen Partie, die sich in diese eingeschlichen hatten, wurden entfernt.",
        'repair.skills.t':                 "Fähigkeiten dieser Partie",
        'repair.skills.ok':                "In Ordnung ({n} Fähigkeiten).",
        'repair.skills.bad':               "Du hast {n} Fähigkeiten, aber mit den gefällten Bäumen können nur {m} Relikte erschienen sein: Sie stammen aus einer früheren Partie. Beim Beheben werden sie entfernt, und die Relikte beginnen wieder bei den billigsten: Sie kommen öfter, während du weiterfällst.",
        'repair.relics.t':                 "Relikt-Zähler",
        'repair.relics.ok':                "In Ordnung ({n} Relikte in dieser Partie gesammelt).",
        'repair.relics.bad':               "Er ist kaputt ({n}): Deshalb sagt jedes Relikt, dass es keine Verbesserungen mehr gibt. Das passiert, wenn Stadt und Fähigkeiten zu verschiedenen Zeitpunkten gespeichert wurden. Beim Beheben wird er aus deinen Fähigkeiten neu berechnet, und Relikte bieten wieder Fähigkeiten an.",
        'repair.relics_fixed':             "Der Relikt-Zähler wurde repariert: Relikte bieten wieder Fähigkeiten an.",
        'repair.res.t':                    "Ressourcen",
        'repair.res.ok':                   "In Ordnung.",
        'repair.res.bad':                  "Einige Ressourcen haben einen unmöglichen Wert ({list}): Sie werden auf 0 gesetzt.",
        'repair.res.souls':                "Seelen",
