        'ach.diqueSeco.name':              "Dok Kering",
        'ach.diqueSeco.desc':              "Keringkan semua air dari dok.",
        'ach.barcoRelampago.name':         "Kapal Kilat",
        'ach.barcoRelampago.desc':         "Bangun kapal dan berlayar dalam 3 jam sejak mulai membuat lambung pertama.",
        'ach.todosAUna.name':              "Bersatu Padu",
        'ach.todosAUna.desc':              "Kerahkan semua penduduk (100 atau lebih) dan semua bagal untuk membangun kapal sekaligus.",
        'ach.ribereno.name':               "Warga Bantaran",
        'ach.ribereno.desc':               "Punya 10 Nelayan berdiri sekaligus.",
        'ach.cauceNuevo.name':             "Alur Baru",
        'ach.cauceNuevo.desc':             "Punya 100 parit tergali sekaligus.",
        'ach.faroEnLaNiebla.name':         "Mercusuar dalam Kabut",
        'ach.faroEnLaNiebla.desc':         "Nyalakan Mercusuar yang terhubung ke jalan.",
        'ach.astilleroPlenoRendimiento.name': "Galangan Kerja Penuh",
        'ach.astilleroPlenoRendimiento.desc': "Buat 10 perahu di Galangan Kapal.",
        'ach.bosqueDeRibera.name':         "Hutan Bantaran",
        'ach.bosqueDeRibera.desc':         "Kumpulkan 10 relik pesisir.",
        'ach.legadoDelRio.name':           "Warisan Sungai",
        'ach.legadoDelRio.desc':           "Klaim semua tingkat Warisan di Dunia 2.",
        'ach.alOtroLado.name':             "Ke Seberang",
        'ach.alOtroLado.desc':             "Tebang pohon di seberang sungai.",
        'ach.granFlota.name':              "Armada Besar",
        'ach.granFlota.desc':              "Punya 100 perahu aktif sekaligus.",
        'ach.vegaPerfecta.name':           "Lembah Sempurna",
        'ach.vegaPerfecta.desc':           "Punya 25 ladang yang semua petaknya di tanah hijau.",
        'ach.tierraFertil.name':           "Tanah Subur",
        'ach.tierraFertil.desc':           "Punya bangunan yang berproduksi di 100 petak hijau sekaligus.",
        'ach.tierraGanada.name':           "Tanah Reklamasi",
        'ach.tierraGanada.desc':           "Punya bangunan yang berproduksi di 1.000 petak hijau sekaligus.",
        'ach.unaSolaOrilla.name':          "Satu Tepian Saja",
        'ach.unaSolaOrilla.desc':          "Tebang 3.000 pohon dalam satu permainan tanpa menebang satu pun di seberang sungai.",
        'ach.masVerdeQueMarron.name':      "Lebih Hijau daripada Cokelat",
        'ach.masVerdeQueMarron.desc':      "Punya lebih banyak tanah subur (hijau) daripada gersang (cokelat) di wilayahmu, dengan 3.000 petak atau lebih.",
        'ach.secano.name':                 "Tadah Hujan",
        'ach.secano.desc':                 "Capai 150 penduduk tanpa membangun ladang, peternakan domba, pohon buah, kebun kapas, atau toko roti dalam permainan ini.",
        'ach.noPican.name':                "Umpan Tak Disambar",
        'ach.noPican.desc':                "Capai 150 penduduk tanpa menangkap seekor ikan pun dalam permainan ini.",
        'ach.colonosOtraOrilla.name':      "Pemukim Seberang",
        'ach.colonosOtraOrilla.desc':      "Capai 150 penduduk tanpa membangun satu rumah pun di sisi sungai tempat perkemahan dalam permainan ini: seberangi dan dirikan pusat kota di sana.",
        'ach.talaPacificaRio.name':        "Tebang Damai di Bantaran",
        'ach.talaPacificaRio.desc':        "Bersihkan seluruh hutan Dunia 2, di kedua sisi sungai, tanpa membongkar satu bangunan pun. Memindah Pos Penebang dan membangun atau menghapus jalan serta menimbun parit diperbolehkan.",
        'ach.talaPacifica.name':           "Tebang Damai",
        'ach.talaPacifica.desc':           "Bersihkan seluruh hutan tanpa membongkar satu bangunan pun. Memindah Pos Penebang dan membangun atau menghapus jalan diperbolehkan.",
        'ach.ciudadFluvial.name':          "Kota Sungai",
        'ach.ciudadFluvial.desc':          "Punya 40 rumah atau lebih berdiri, setengahnya (20) di tiap sisi sungai.",
        'ach.suministrosCosta.name':       "Pemulung Kapal Karam",
        'ach.suministrosCosta.desc':       "Kumpulkan 200 perbekalan yang hanyut di lepas pantai (total, dari semua permainanmu).",
        'ach.dondeCabeUno.name':           "Sebenarnya Muat Berdua",
        'ach.dondeCabeUno.desc':           "",
        'ach.cincoArcos.name':             "Lima Lengkung",
        'ach.cincoArcos.desc':             "Buat rute perahumu melewati bawah 5 jembatan tinggi.",
        'ach.coinInfo':                    "Setiap pencapaian juga memberi berlian saat terbuka — jumlahnya tergantung kelangkaannya (lihat tiap kategori di bawah).",
        'ach.tier.coinHint':               "Berlian yang diberikan tiap pencapaian dengan kelangkaan ini saat terbuka",
