        'tuto.2.title':                    "Twój pierwszy mieszkaniec",
        'tuto.2.desc':                     "Zaznacz Ratusz i zatrudnij pierwszego mieszkańca za drewno.",
        'tuto.2.title_m2':                 "Więcej rąk",
        'tuto.2.desc_m2':                  "Na brzeg dotarło z tobą dwoje rozbitków. Zaznacz Ratusz i zatrudnij za drewno jeszcze jednego mieszkańca.",
        'tuto.3.title':                    "Załóż wioskę",
        'tuto.3.desc':                     "Zatrudniaj mieszkańców, aż będzie ich 5. ({n}/5 {res})",
        'tuto.4.title':                    "Obóz drwali",
