        'spectator.name_title':            "Nazwij swoje miasto",
        'spectator.name_desc':             "Ta nazwa pojawi się w nagłówku u każdego, kto otworzy link.",
        'spectator.name_placeholder':      "np. Dębowa Wola",
        'spectator.your_name_label':       "Twoje imię (zapamiętamy je na następny raz)",
        'spectator.your_name_placeholder': "np. Janek — zostaw puste, by być „Gościem”",
        'spectator.visit_btn':             "Miasta społeczności",
        'spectator.browse_title':          "Miasta społeczności",
