        'spectator.my_cities':             "Moje miasta",
        'spectator.hidden_badge':          "Ukryte",
        'spectator.hide_btn':              "Ukryj",
        'spectator.unhide_btn':            "Pokaż",
        'spectator.browse_empty':          "Nikt jeszcze nie udostępnił miasta. Bądź pierwszy!",
        'spectator.browse_failed':         "Nie udało się wczytać miast. Spróbuj ponownie.",
        'spectator.visit_placeholder':     "np. nrxshuyay",
        'spectator.visit_go':              "Odwiedź",
        'howto.goal_title':                "Cel",
        'howto.goal_desc':                 "Wytnij wszystkie drzewa na mapie, by poszerzyć swoje terytorium. Gra kończy się, gdy nie zostanie ani jedno.",
        'howto.villagers_title':           "Mieszkańcy",
        'howto.villagers_desc':            "Werbuj mieszkańców za drewno, żywność lub tkaniny i przydzielaj ich do budynków (farma, kamieniołom, obóz drwali...), by pracowali na własną rękę.",
        'howto.cityAdjacency_title':       "Budynki miejskie",
        'howto.cityAdjacency_desc':        "Dom, Piekarnia, Kościół, Warsztat, Urząd skarbowy, Karczma, Targ miejski, Teatr i Tartak muszą stykać się z INNYM budynkiem miejskim (lub z Ratuszem) ORAZ mieć w pobliżu podłączoną drogę. Inaczej są odizolowane i się nie liczą — odizolowany dom nie dodaje na przykład populacji.",
        'howto.roads_title':               "Drogi",
        'howto.roads_desc':                "Wszystkie pozostałe budynki (farmy, kamieniołomy, obozy drwali...) muszą tylko dotykać podłączonej drogi lub Ratusza — nie muszą stać obok innego budynku.",
        'howto.skills_title':              "Drzewko umiejętności",
        'howto.skills_desc':               "Odkrywaj mapę i znajduj relikwie, by odblokowywać stałe ulepszenia w drzewku umiejętności.",
        'howto.legado_title':              "Dziedzictwo (prestiż)",
        'howto.legado_desc':               "Po zebraniu określonej liczby relikwii możesz zrestartować rozgrywkę w zamian za stałe bonusy, które zostają na zawsze, także po restarcie.",
        'howto.tip_well_title':            "Nawadniaj farmy",
        'howto.tip_well_desc':             "Studnia obok farmy daje jej ×3 szybkość zbiorów i ×2 udźwig. Nie potrzebuje drogi i jest tania: stawiaj ją, kiedy tylko możesz.",
        'howto.tip_mules_title':           "Rozsuń oba targi",
        'howto.tip_mules_desc':            "Muły przynoszą tym więcej złota, im dalej Targ wiejski jest od Targu miejskiego, a bonus rośnie szybciej niż odległość. Liczy się odstęp między budynkami, a nie droga, którą przejdzie muł: kręta droga tylko go spowalnia.",
        'howto.tip_tavern_title':          "Karczmy",
        'howto.tip_tavern_desc':           "Z ulepszeniem Nocleg Karczma daje +1 populacji za każdy dom w promieniu 3 pól. Przy dwóch Karczmach dom w zasięgu obu liczy się tylko raz: rozstaw je tak, by obejmowały różne domy.",
        'howto.tip_forest_title':          "Gdy las się kończy",
        'howto.tip_forest_desc':           "Wycięte drzewa nigdy nie odrastają. Plantacja drzew to jedyne źródło drewna, które się nie wyczerpuje.",
        'wipe.btn.cancel':                 "Anuluj",
        'deleteSlot.title':                "Usunąć zapis {n}?",
        'deleteSlot.desc':                 "Ten zapis zostanie całkowicie usunięty: postęp, umiejętności i Dziedzictwo. Tego nie da się cofnąć.",
        'deleteSlot.confirm':              "Tak, usuń",
