        'ach.tierraFertil.name':           "Verimli Toprak",
        'ach.tierraFertil.desc':           "Aynı anda 100 yeşil karede üretim yapan binaların olsun.",
        'ach.tierraGanada.name':           "Kazanılmış Toprak",
        'ach.tierraGanada.desc':           "Aynı anda 1.000 yeşil karede üretim yapan binaların olsun.",
        'ach.unaSolaOrilla.name':          "Tek Kıyı",
        'ach.unaSolaOrilla.desc':          "Bir oyunda nehrin karşı yakasında hiç ağaç kesmeden 3.000 ağaç kes.",
        'ach.masVerdeQueMarron.name':      "Kahverengiden Çok Yeşil",
        'ach.masVerdeQueMarron.desc':      "3.000 ya da daha fazla karelik topraklarında verimli (yeşil) toprak kurak (kahverengi) topraktan fazla olsun.",
        'ach.secano.name':                 "Kuru Tarım",
