function t(key, vars = {}) {
    // Textos propios de un mundo (worlds/worldN.js → lang): clave normal → clave del mundo. Lo fija
    // main.js al aplicar el mundo (ver _applyWorldRiver).
    if (window.FN_LANG_REMAP && window.FN_LANG_REMAP[key]) key = window.FN_LANG_REMAP[key];
    let str = LANG_DATA[currentLang]?.[key] ?? (currentLang !== 'es' ? LANG_DATA.en?.[key] : undefined) ?? LANG_DATA['es']?.[key] ?? key;
    const isMobile = typeof _MQ_PORTRAIT !== 'undefined' && _MQ_PORTRAIT.matches;
    for (const [token, byLang] of Object.entries(_DEVICE_TOKENS)) {
        const marker = `{${token}}`;
        if (!str.includes(marker)) continue;
        const pair = byLang[currentLang] || byLang.en;
        str = str.replaceAll(marker, isMobile ? pair[1] : pair[0]);
    }
    for (const [k, v] of Object.entries(vars)) {
        str = str.replaceAll(`{${k}}`, v);
    }
    return str;
}

// Actualiza todos los elementos con data-t (innerText) o data-t-html (innerHTML)
function applyLang() {
    document.querySelectorAll('[data-t]').forEach(el => {
        el.innerText = t(el.dataset.t);
    });
    document.querySelectorAll('[data-t-html]').forEach(el => {
        el.innerHTML = t(el.dataset.tHtml);
    });
    // Igual que data-t pero sobre el atributo title (tooltips estáticos) — ver btnScreensaver/
    // btnExitScreensaver en index.html.
    document.querySelectorAll('[data-t-title]').forEach(el => {
        el.title = t(el.dataset.tTitle);
    });
    // Igual, pero sobre el atributo placeholder — ver #discordCodeInput en index.html.
    document.querySelectorAll('[data-t-placeholder]').forEach(el => {
        el.placeholder = t(el.dataset.tPlaceholder);
    });
    // Avisos de reliquias (se montan en JS, sin data-t): se vuelven a pintar en el idioma nuevo.
    if (typeof _renderRelicQueue === 'function') { try { _renderRelicQueue(); } catch (e) {} }
    // Panel Cómo Jugar / Controles (se monta en JS): se vuelve a pintar en el idioma nuevo
    if (typeof _renderHowTo === 'function') { try { _renderHowTo(); } catch (e) {} }
    // Tienda (tarjetas montadas en JS)
    if (typeof _renderShop === 'function') { try { _renderShop(); } catch (e) {} }
    if (typeof _renderSkinPanel === 'function') { try { _renderSkinPanel(); } catch (e) {} }
    // Botón del acelerador de tiempo: se rellena antes de aplicar el idioma guardado y solo se repintaba al cambiar la cuenta atrás
    if (typeof _updateAdTimeBonusButton === 'function') { try { _updateAdTimeBonusButton(); } catch (e) {} }
}

document.addEventListener('DOMContentLoaded', applyLang);
